-- ======================================================================
-- COHORT B FULL RUN — backfill 601 legacy shades with tinting history
-- ======================================================================

-- WHAT THIS DOES:
--  1. Insert 118 new CHILD sampling_register rows (e.g. "1322925-1")
--  2. Insert 118 new sampling_recipes rows (one per child)
--  3. Insert 2,830 new sampling_usage_log rows
--  4. Backfill recipeId on the new usage_log rows
--  5. Backfill siteId on new usage_log + register rows via delivery_point_master

-- Step 1 — 118 new CHILD sampling_register rows
-- ----------------------------------------------------------------------

-- Step 2 — 118 new sampling_recipes rows (one per child)
-- ----------------------------------------------------------------------

-- Step 3 — 2,830 new sampling_usage_log rows
-- ----------------------------------------------------------------------

-- Step 4 — Backfill recipeId on the new usage_log rows
-- ----------------------------------------------------------------------
UPDATE sampling_usage_log ul
SET "recipeId" = sr.id
FROM sampling_recipes sr
WHERE ul."recipeId" IS NULL
  AND ul."samplingNo" = sr."samplingNo"
  AND UPPER(TRIM(ul."skuCodeRaw")) = UPPER(TRIM(sr."skuCode"));

-- Step 5 — Backfill siteId on new register + usage_log rows
-- ----------------------------------------------------------------------
UPDATE sampling_register sr
SET "siteId" = dpm.id
FROM delivery_point_master dpm
WHERE sr."siteId" IS NULL
  AND sr."siteNameRaw" IS NOT NULL
  AND LOWER(TRIM(sr."siteNameRaw")) = LOWER(TRIM(dpm."customerName"));

UPDATE sampling_usage_log ul
SET "siteId" = dpm.id
FROM delivery_point_master dpm
WHERE ul."siteId" IS NULL
  AND ul."siteNameRaw" IS NOT NULL
  AND LOWER(TRIM(ul."siteNameRaw")) = LOWER(TRIM(dpm."customerName"));

-- ======================================================================
-- VERIFICATION QUERIES
-- ======================================================================

-- 6a. New child sampling numbers created
SELECT COUNT(*) AS new_children
FROM sampling_register
WHERE "samplingNo" LIKE '%-%' AND "samplingNo" NOT LIKE '26-%';
-- Expected: 118

-- 6b. Cohort B parents now have usage history
SELECT COUNT(DISTINCT "samplingNo") AS legacy_snos_with_usage
FROM sampling_usage_log
WHERE "samplingNo" NOT LIKE '26-%';
-- Expected: ~4,200+ (3,566 cohort A + ~601 cohort B + 118 children)

-- 6c. usage_log recipeId link rate
SELECT
  COUNT(*) AS total_usage,
  COUNT("recipeId") AS linked,
  ROUND(100.0 * COUNT("recipeId") / COUNT(*), 1) AS link_pct
FROM sampling_usage_log
WHERE "samplingNo" NOT LIKE '26-%';
-- Expected: link_pct >= 97%

-- 6d. Spot check #1322925 — should now show 4 canonical usage rows + 1 child shade
SELECT "samplingNo", COUNT(*) AS usage_rows
FROM sampling_usage_log
WHERE "samplingNo" IN ('1322925', '1322925-1')
GROUP BY "samplingNo" ORDER BY "samplingNo";
-- Expected: 1322925=4, 1322925-1=3

-- 6e. Verify each child has exactly 1 recipe and it is primary
SELECT
  "samplingNo",
  COUNT(*) AS recipe_count,
  SUM(CASE WHEN "isPrimary" THEN 1 ELSE 0 END) AS primary_count
FROM sampling_recipes
WHERE "samplingNo" LIKE '%-%' AND "samplingNo" NOT LIKE '26-%'
GROUP BY "samplingNo"
HAVING COUNT(*) != 1 OR SUM(CASE WHEN "isPrimary" THEN 1 ELSE 0 END) != 1;
-- Expected: 0 rows